CREATE TABLE IF NOT EXISTS
"DatosCETEVI"(
    "id" int GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Id" text,
    "Tiempo" real,
    "Fuerza" real,
    "Corriente" real
);

CREATE TABLE IF NOT EXISTS
"PruebasCETEVI"(
    "Id" text PRIMARY KEY,
    "Muestras" integer,
    "Tiempo" real,
    "Orientacion" text,
    "FMax" real,
    "IMax" real,
    "Grosor" real,
    "Material" text,
    "Diametro" real
);   
